document.querySelector('#quote')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget; if(!f.reportValidity())return; const d=new FormData(f);const text=`Merhaba Berk PPF Studio,\nAraç: ${d.get('car')}\nHizmet: ${d.get('service')}\nNot: ${d.get('note')||'-'}`;const phone=f.dataset.whatsapp.replace(/\D/g,'');if(phone){window.location.href=`https://wa.me/${phone}?text=${encodeURIComponent(text)}`;return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='berk-ppf-teklif-talebi.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>{URL.revokeObjectURL(url);window.location.href='/tesekkurler.html'},500)});
